// The expressions that docs/configuration/supported-databases/sqlite.md gives, in "Values generated by the database",
// for a value that SQLite writes on its own, like the default of a column. Each one runs as the default of a column on
// a real SQLite: the text it stores must have the shape of what the library writes in that format, and it must read as
// the current moment. The table is read from the page, so a format or an expression that changes there is tested
// here as it is published. It runs in a process of its own for each zone: see valuesGeneratedByTheDatabase/probe.ts.

import { spawnSync } from 'node:child_process'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { describe, expect, test } from '../../lib/testRunner.js'
import type { SqliteDateTimeFormat } from '../../../src/connections/SqliteConfiguration.js'

const page = readFileSync(fileURLToPath(new URL('../../../docs/configuration/supported-databases/sqlite.md', import.meta.url)), 'utf8')
const section = page.slice(page.indexOf('### Values generated by the database'))
const rows = section.slice(0, section.indexOf('\n\n', section.indexOf('|---'))).split('\n').filter(line => line.startsWith('| `'))
    .map(line => {
        const cells = line.slice(2, -2).split(' | ')
        const code = (cell: string) => [...cell.matchAll(/`([^`]+)`/g)].map(match => match[1]!)
        return { format: code(cells[0]!)[0]! as SqliteDateTimeFormat, dateTime: code(cells[1]!), time: code(cells[2]!)[0]! }
    })

const formats: SqliteDateTimeFormat[] = [
    'localdate seconds as text', 'localdate milliseconds as text',
    'localdate seconds as text using T separator', 'localdate milliseconds as text using T separator',
    'UTC seconds as text', 'UTC milliseconds as text',
    'UTC seconds as text using T separator', 'UTC milliseconds as text using T separator',
    'UTC seconds as text using Z timezone', 'UTC milliseconds as text using Z timezone',
    'UTC seconds as text using T separator and Z timezone', 'UTC milliseconds as text using T separator and Z timezone',
    'Julian day as real number', 'Unix time seconds as integer', 'Unix time milliseconds as integer',
]

const probe = fileURLToPath(new URL('./valuesGeneratedByTheDatabase/probe.ts', import.meta.url))
const runtimeArguments = typeof globalThis.Bun !== 'undefined' ? [probe] : ['--import', 'tsx', probe]

describe('SQLite: the values generated by the database, as the SQLite page gives them', () => {
    test('the page has one row for each format', () => {
        expect(rows.map(row => row.format)).toEqual(formats)
    })

    for (const zone of ['UTC', 'Europe/Madrid', 'America/New_York']) {
        test(`a default with each expression of the page stores what the library writes, in ${zone}`, () => {
            const result = spawnSync(process.execPath, [...runtimeArguments, JSON.stringify(rows)], { encoding: 'utf8', env: { ...process.env, TZ: zone } })
            expect(result.stderr).toBe('')
            expect(result.status).toBe(0)
            expect(JSON.parse(result.stdout)).toEqual([])
        }, 60_000)
    }
})
